    s = clean(size)
    if not s:
        return ""
    lower = s.lower()
    for src, dest in AGE_TO_PRINT.items():
        if src.lower() == lower:
            return dest
    for src, dest in LETTER_TO_MEN_PRINT.items():
        if src.lower() == lower:
            return dest
    if s in PE_AGE:
        age_sr = PE_AGE[s]
        return AGE_TO_PRINT.get(age_sr, AGE_TO_PRINT.get(age_sr + " Years", ""))
